//    https://www.fon.hum.uva.nl/david/ba_shs/2009/klatt-1980.pdf
//  - MAME votrax.cpp (BSD-3-Clause, Olivier Galibert): the filter capacitor
//    values, used to work out which 4-bit code gives which frequency.
//
// Method: DUR inverts the strobe to A/R formula against the data sheet
// durations (720 kHz). F1/F3 are the codes whose computed resonance is
// nearest the target; F2 and F2Q are chosen together (frequency first,
// then bandwidth) inside the region where the F2 noise injection filter
// stays stable. VA/FA/FC follow the phonetic class, trimmed against
// levels measured in a port of the MAME circuit model. Stops close at
// tick CLD and build their burst noise silently from tick VD; the next
// phoneme releases it.
//
// PA0 ($03) and PA1 ($3E) are pauses by hard-wired logic on the die, not
// by anything in this table; the emulator applies that rule itself.

struct SC01Phone {
  uint8_t f1, f2, f2q, f3;  // 4-bit filter codes
  uint8_t va, fa, fc;       // 4-bit amplitudes
  uint8_t cld, vd;          // 4-bit tick delays
  uint8_t cl;               // closure bit
  uint8_t dur;              // 7-bit tick length
};

